"""One complete original front roof fascia with Boolean interruptions preserved."""
from pathlib import Path
import numpy as np,trimesh,json,hashlib
R=Path(__file__).resolve().parent;H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();expected='b58ec49d9ac34394b02ed4c57ed4e67e6150877b32339a4d14d4fc80c497a1e9';assert H(R/'model.stl')==expected
m=trimesh.load(R/'model.stl',force='mesh',process=True);assert len(m.faces)==4726
t=m.triangles;n=m.face_normals;e=.0001;a=np.full(len(t),1,np.int32);D={}
ids=np.flatnonzero(np.abs(t[:,:,1]+41).max(1)<e)
assert len(ids)==62
edges=m.face_adjacency;edges=edges[np.isin(edges[:,0],ids)&np.isin(edges[:,1],ids)]
pcs=trimesh.graph.connected_components(edges,nodes=ids,min_len=1);assert len(pcs)==1
D['complete_front_roof_fascia']=ids.tolist();a[ids]=0
ad=m.face_adjacency;cop=(n[ad[:,0]]*n[ad[:,1]]).sum(1)>.999999;cs=trimesh.graph.connected_components(ad[cop],nodes=np.arange(len(t)),min_len=1);assert all(len(set(a[c]))==1 for c in cs);assert np.bincount(a).tolist()==[62,4664]
pal=[('NCNU Sports Ball Hall observed complete front roof fascia lightgray','#C7CECC'),('UNVERIFIED main walls entrance windows roofs neutral','#B8BAB5')]
np.savez_compressed(R/'color-mesh.npz',vertices=m.vertices,faces=m.faces,materials=a);(R/'palette.json').write_text(json.dumps(pal,indent=2)+'\n');q={'palette':[{'id':i,'name':name,'hex':col,'faces':int((a==i).sum())}for i,(name,col)in enumerate(pal)],'domain_face_indices':D,'coplanar_components':len(cs),'partial_color_incomplete':True,'fully_colored_exterior':False,'geometry_policy':'4726 original triangles unchanged','limits':['Entire curved roof upper skin, underside and opposite eave lack complete visual evidence and remain unknown neutral.', 'Diamond glazing backings contain varying reflections and frames; no blanket cyan/blue.', 'Main brick wall/pilasters and side buttresses mix gray horizontal courses with brick without matching continuous face boundaries; no all-red masonry family.', 'Gussets/tie rods appear pale but full original surfaces include orientation/occlusion uncertainty; outside this deliberately bounded recommendation.', 'Door backings, lettering/emblem, lower obscured areas, ground, unknown rear and all unlisted triangles remain neutral.', 'This existing item has two prior depth-preview materials, not verified real-world colors. Count delta0; no new building or monochrome classification.', 'New source-evidenced variant applies only62 fascia faces; every other face returns to unknown neutral, including former dark depth cues. Preserve original scene/3MF/preview and previous audit evidence unchanged.', 'Preserve4726 triangles and all geometry. No subdivisions, new texture or transparent glass claim.', 'Only five-diamond ball hall volume; no swimming-pool wing, fitness/hydrotherapy area or connecting entrance hall.']};(R/'appearance-materials.json').write_text(json.dumps(q,indent=2)+'\n');(R/'COLOR-ASSIGNMENT-QA.json').write_text(json.dumps({'status':'PASS','original_STL_sha256':expected,'triangles':4726,'color_mesh_sha256':H(R/'color-mesh.npz')},indent=2));print(q['palette'],'components',len(cs))
